const html = String($json.data || '');
const wanted = String($('Target Country Form').first().json.Country || '').trim().toLowerCase();
if (!wanted) { throw new Error('No country provided in the form.'); }
const re = /href="(\/partners\/country\/([a-z0-9-]+-\d+))"[^>]*>([\s\S]*?)<\/a>/gi;
const lev = (a, b) => {
  const la = a.length; const lb = b.length;
  if (!la) { return lb; }
  if (!lb) { return la; }
  const d = [];
  for (let i = 0; i <= la; i++) { d[i] = [i]; }
  for (let j = 0; j <= lb; j++) { d[0][j] = j; }
  for (let i = 1; i <= la; i++) {
    for (let j = 1; j <= lb; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
    }
  }
  return d[la][lb];
};
let m; const seen = {}; const candidates = [];
while ((m = re.exec(html)) !== null) {
  const text = m[3].replace(/<[^>]*>/g, ' ').replace(/[0-9]/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
  if (!text || seen[text]) { continue; }
  seen[text] = true;
  candidates.push({ text, slug: m[2], path: m[1] });
}
let found = null; let partial = null; let fuzzy = null; let fuzzyDist = Infinity;
for (const c of candidates) {
  if (c.text === wanted) { found = c; break; }
  if (!partial && (c.text.indexOf(wanted) !== -1 || wanted.indexOf(c.text) !== -1)) { partial = c; }
  const dist = lev(c.text, wanted);
  if (dist < fuzzyDist) { fuzzyDist = dist; fuzzy = c; }
}
const threshold = Math.max(2, Math.floor(wanted.length * 0.34));
const pick = found || partial || (fuzzy && fuzzyDist <= threshold ? fuzzy : null);
if (!pick) { throw new Error('Country not found in the Odoo partner directory: ' + wanted + '. Please check the spelling.'); }
return [{ json: { country: pick.text, inputCountry: wanted, slug: pick.slug, baseUrl: 'https://www.odoo.com/partners/country/' + pick.slug } }];

const html = String($json.data || '');
const base = String($('Resolve Country Slug').first().json.baseUrl);
let total = 0;
const tm = html.match(/'grade_id_count':\s*(\d+),\s*'grade_id':\s*\(0,/);
if (tm) { total = parseInt(tm[1], 10); }
const linkRe = /\/partners\/([a-z0-9][a-z0-9-]*-\d+)/g;
const set = new Set();
let lm;
while ((lm = linkRe.exec(html)) !== null) { set.add(lm[1]); }
const perPage = set.size;
let pages = 1;
if (perPage > 0 && total > perPage) { pages = Math.ceil(total / perPage); }
if (pages > 500) { pages = 500; }
const out = [];
for (let i = 1; i <= pages; i++) {
  out.push({ json: { page: i, pageUrl: i === 1 ? base : (base + '/page/' + i), total: total, perPage: perPage } });
}
return out;

const origin = 'https://www.odoo.com';
const linkRe = /\/partners\/([a-z0-9][a-z0-9-]*-\d+)/g;
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const html = String(item.json.data || '');
  let m;
  while ((m = linkRe.exec(html)) !== null) {
    const slug = m[1];
    if (seen.has(slug)) { continue; }
    seen.add(slug);
    out.push({ json: { partnerSlug: slug, profileUrl: origin + '/partners/' + slug } });
  }
}
return out;

const html = String($json.data || '');
const src = $('Extract Partner Links').item.json;
let name = '';
const t = html.match(/<title>([\s\S]*?)<\/title>/i);
if (t) { name = t[1].replace(/\s*\|\s*Odoo\s*$/i, '').replace(/\s+/g, ' ').trim(); }
if (!name) { name = String(src.partnerSlug || '').replace(/-\d+$/, '').replace(/-/g, ' ').replace(/\b\w/g, function (c) { return c.toUpperCase(); }); }
let website = '';
const aRe = /href="(https?:\/\/[^"\x27]+)"/gi;
const bad = ['odoo.com','facebook.com','twitter.com','x.com','linkedin.com','instagram.com','youtube.com','youtu.be','google.com','maps.goo','apps.odoo','cdn.','gstatic','googleapis','fontawesome','schema.org','w3.org','wa.me','t.me','tiktok.com'];
let a;
while ((a = aRe.exec(html)) !== null) {
  const url = a[1];
  const low = url.toLowerCase();
  if (bad.some(function (b) { return low.indexOf(b) !== -1; })) { continue; }
  website = url.split('#')[0].split('?')[0];
  break;
}
const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const emails = Array.from(new Set((html.match(emailRe) || []).filter(function (e) {
  const l = e.toLowerCase();
  return !/\.(png|jpg|jpeg|gif|svg|webp)$/i.test(l) && l.indexOf('odoo.com') === -1 && l.indexOf('example.com') === -1 && l.indexOf('sentry') === -1;
})));
return { json: { profileUrl: src.profileUrl, partnerSlug: src.partnerSlug, name: name, website: website, emailsFromProfile: emails } };

const site = String($json.data || '');
const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const siteEmails = (site.match(emailRe) || []).filter(function (e) {
  return !/\.(png|jpg|jpeg|gif|svg|webp|css|js)$/i.test(e);
});
const prof = $('Parse Profile').item.json;
const merged = Array.from(new Set([].concat(prof.emailsFromProfile || [], siteEmails)))
  .filter(function (e) {
    const l = e.toLowerCase();
    return l.indexOf('sentry') === -1 && l.indexOf('wixpress') === -1 && l.indexOf('example.com') === -1 && l.indexOf('.png') === -1;
  })
  .slice(0, 25);
return { json: { profileUrl: prof.profileUrl, name: prof.name, website: prof.website, candidateEmails: merged } };

