const raw = String($json.text || '').trim();
const m = raw.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
const email = m ? m[0] : '';
const p = $('Collect Email Candidates').item.json;
return { json: { email: email, name: p.name, website: p.website, profileUrl: p.profileUrl } };
